var t=`0784-xima`;var n=`world-0784`;var s=`MZ`;var r=`eastern-africa`;var a=8;var o=44;var l={en:`Xima`,ua:`Шіма`};var g={en:`Xima is a Mozambique classic prepared with cornmeal. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Шіма, страва кухні країни Мозамбік зі складниками: кукурудзяна крупа дрібного помелу. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var d=[{en:`Cook the listed ingredients in simmering water for about 9 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 9 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:9,i:[[`water`,1050,`ml`],[`table-salt`,5,`g`]]},{en:`Slowly stir the grains into the simmering liquid; cook over low heat for about 24 minutes, stirring to prevent sticking.`,ua:`Повільно всипте крупу в гарячу рідину; варіть на слабкому вогні приблизно 24 хвилин, помішуючи, щоб не пристала до дна.`,t:[`absorption-cooking`],m:24,i:[[`cornmeal`,380,`g`]]},{en:`Roll or press the prepared dough evenly into the desired thickness and shape.`,ua:`Розкачайте або розпластайте підготовлене тісто рівномірним шаром потрібної товщини та форми.`,t:[`pressing`,`rolling-out-dough`],m:8,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`unsalted-butter`,30,`g`]]}];var u={slug:t,id:n,country:`MZ`,region:r,servings:8,minutes:44,title:l,text:g,steps:d};export{s as country,u as default,n as id,o as minutes,r as region,a as servings,t as slug,d as steps,g as text,l as title};